import React from 'react';

export const Footer = () => {
  return (
    <footer className="footer-section" style={{ padding: '40px 20px', textAlign: 'center', backgroundColor: '#222', color: 'white' }}>
      <p>&copy; {new Date().getFullYear()} Your Company. All rights reserved.</p>
      <p>This is the footer section.</p>
    </footer>
  );
};
